export const getLocalizedPageMeta = (path: string, lang: string): PageMeta | null => {
  const clean = path === '' ? '/' : path.replace(/\/+$/, '') || '/';
  const byLang = SEO_META[lang] || SEO_META['en'];
  return byLang?.[clean] || SEO_META['en']?.[clean] || null;
};
